WIDGETS.polar=host=>{let pt='cardioid',ang=0;
 const svg=()=>{const R=110,cx=130,cy=130;const f=PATTERNS[pt][1];let d='';for(let i=0;i<=360;i+=3){const t=i*Math.PI/180;const r=Math.abs(f(t))*R;d+=(i?'L':'M')+(cx+r*Math.sin(t)).toFixed(1)+' '+(cy-r*Math.cos(t)).toFixed(1)}const a=ang*Math.PI/180;const sx=cx+R*1.05*Math.sin(a),sy=cy-R*1.05*Math.cos(a);
  return`<svg viewBox="0 0 260 260" class="polar" role="img" aria-label="${PATTERNS[pt][0]} polar pattern"><circle cx="${cx}" cy="${cy}" r="${R}" class="ring"/><circle cx="${cx}" cy="${cy}" r="${R*.5}" class="ring"/><line x1="${cx}" x2="${cx}" y1="${cy-R}" y2="${cy+R}" class="ring"/><line y1="${cy}" y2="${cy}" x1="${cx-R}" x2="${cx+R}" class="ring"/><path d="${d}Z" class="pat"/><rect x="${cx-7}" y="${cy-16}" width="14" height="30" rx="7" class="mic"/><text x="${cx}" y="16" text-anchor="middle" class="lbl">front</text><text x="${cx}" y="254" text-anchor="middle" class="lbl">back</text><circle cx="${sx}" cy="${sy}" r="9" class="src"/></svg>`};
 const lvl=()=>Math.abs(PATTERNS[pt][1](ang*Math.PI/180));
 const txt=()=>{const L=lvl();return`<p><b>${L<.02?'Silent: this is the null':dB(L).toFixed(1)+' dB'}</b> <span class="hint">compared with straight on</span></p><p class="hint">${ang===0?'On-axis: full level, full detail.':ang<60?'Slightly off-axis: a touch duller.':ang<120?'Off to the side: quieter and darker.':'Behind the mic.'}</p>`};
 const upd=()=>{host.querySelector('.polar').outerHTML=svg();host.querySelector('#pangv').textContent=ang+'°';host.querySelector('#ptxt').innerHTML=txt()};
 const render=()=>{host.innerHTML=`<h3>Polar patterns</h3>${pillsHTML('pp',Object.entries(PATTERNS).map(([k,v])=>[k,v[0]]),pt)}<div class="polwrap">${svg()}<div class="stack"><label class="tempo">Sound comes from <input type="range" id="pang" min="0" max="180" value="${ang}"> <span id="pangv">${ang}°</span></label><div id="ptxt">${txt()}</div><button class="btn primary small" id="ppl">${ICON.play} Hear it</button></div></div>`;
  bindPills(host,(g,v)=>{pt=v;render();hear()});host.querySelector('#pang').oninput=e=>{ang=+e.target.value;upd()};host.querySelector('#pang').onchange=()=>hear();host.querySelector('#ppl').onclick=hear};
 const hear=()=>playThrough('strum',(c,src,nodes)=>{const g=c.createGain();g.gain.value=lvl()*1.6;const hs=c.createBiquadFilter();hs.type='highshelf';hs.frequency.value=3500;hs.gain.value=pt==='omni'?-2*Math.sin(ang*Math.PI/360):-10*Math.sin(ang*Math.PI/360);src.connect(hs).connect(g).connect(MASTER);nodes.push(g,hs);return g});
 render()};
/* placement */
WIDGETS.placement=host=>{const SRC={vocal:{name:'Vocal',clip:'voice',aims:[['mouth','Straight at the mouth'],['off','Slightly off-axis']]},acoustic:{name:'Acoustic guitar',clip:'strum',aims:[['hole','The soundhole'],['neck','12th–14th fret'],['bridge','The bridge']]},amp:{name:'Guitar amp',clip:'strum',aims:[['centre','Centre of the cone'],['edge','Edge of the cone']]}};
 let src='acoustic',dist=20,aim='neck',room=true;
 const params=()=>{const prox=Math.max(0,11*(1-Math.log(dist/2)/Math.log(20)));let low=prox,mid=0,high=0,boom=0;
  if(src==='acoustic'){if(aim==='hole'){low+=6;boom=1}else if(aim==='bridge'){mid+=3;high-=1;low-=2}}if(src==='amp'){high+=aim==='centre'?4:-5}if(src==='vocal'&&aim==='off')high-=2.5;
  const wet=room?Math.min(.75,Math.pow(dist/100,1.3)*.9):0;return{low,mid,high,wet,lvl:Math.min(1.6,6/Math.max(4,dist)+.25)}};
 const verdict=()=>{const p=params();const w=[];if(p.low>8)w.push('boomy and bass-heavy (proximity effect)');else if(p.low>4)w.push('warm and full');else if(p.low<1&&dist>40)w.push('thin in the low end');if(p.wet>.35)w.push('roomy: lots of the room in the sound');else if(p.wet<.12)w.push('close and dry');if(p.high>2)w.push('bright');if(p.high<-3)w.push('dark and smooth');
  const good=src==='vocal'?dist>=10&&dist<=35:src==='acoustic'?aim==='neck'&&dist>=12&&dist<=35:dist<=6;return`${good?'<b class="good">Good starting point.</b> ':''}Sounds ${w.join(', ')||'balanced'}.`};
 const svg=()=>{const W=300,H=110,sx=50,sy=55;const px=sx+20+dist*2.1,py=sy-Math.sin(0)*0;return`<svg viewBox="0 0 ${W} ${H}" class="place" role="img" aria-label="Top view of the mic and the source"><rect x="${sx-34}" y="${sy-34}" width="58" height="68" rx="10" class="srcbox"/><text x="${sx-5}" y="${sy+4}" text-anchor="middle" class="lbl">${SRC[src].name.split(' ')[0]}</text><line x1="${sx+24}" x2="${px-12}" y1="${sy}" y2="${sy}" class="dim"/><text x="${(sx+24+px)/2}" y="${sy-22}" text-anchor="middle" class="lbl">${dist} cm</text><g transform="translate(${px} ${sy})"><rect x="-12" y="-7" width="30" height="14" rx="7" class="mic"/><text x="3" y="26" text-anchor="middle" class="lbl">mic</text></g></svg>`};
 const render=()=>{const S=SRC[src];if(!S.aims.find(a=>a[0]===aim))aim=S.aims[src==='acoustic'?1:0][0];host.innerHTML=`<h3>Mic placement simulator</h3><p class="hint">Move the mic and press Hear it. This is a simplified model of what really happens, so use it to train your ears, then try it with a real mic.</p>
  ${pillsHTML('ps',Object.entries(SRC).map(([k,v])=>[k,v.name]),src)}<div class="row" style="gap:16px;flex-wrap:wrap;align-items:center;margin-top:8px"><label class="tempo">Distance <input type="range" id="pd" min="2" max="100" value="${dist}"> <span id="pdv">${dist} cm</span></label><label class="pill" style="cursor:pointer"><input type="checkbox" id="proom" ${room?'checked':''}> Untreated room</label></div>
  <div class="pickrow"><span class="eyebrow">Aim at</span>${pillsHTML('pa',S.aims,aim)}</div><div class="scroll">${svg()}</div><p id="pverd">${verdict()}</p><div class="row"><button class="btn primary small" id="phear">${ICON.play} Hear it</button></div>`;
  bindPills(host,(g,v)=>{if(g==='ps')src=v;else aim=v;render();hear()});host.querySelector('#pd').oninput=e=>{dist=+e.target.value;host.querySelector('#pdv').textContent=dist+' cm';host.querySelector('.place').outerHTML=svg();host.querySelector('#pverd').innerHTML=verdict()};host.querySelector('#pd').onchange=hear;host.querySelector('#proom').onchange=e=>{room=e.target.checked;host.querySelector('#pverd').innerHTML=verdict()};host.querySelector('#phear').onclick=hear};
 const hear=()=>{const p=params();playThrough(SRC[src].clip,(c,s,nodes)=>{let head=s;const chain=[];if(src==='amp'){const pre=c.createGain();pre.gain.value=6;const ws=c.createWaveShaper();ws.curve=shaperCurve(3);const lp=c.createBiquadFilter();lp.type='lowpass';lp.frequency.value=4200;const po=c.createGain();po.gain.value=.35;chain.push(pre,ws,lp,po)}
  const lo=c.createBiquadFilter();lo.type='lowshelf';lo.frequency.value=180;lo.gain.value=p.low;const md=c.createBiquadFilter();md.type='peaking';md.frequency.value=1200;md.Q.value=.8;md.gain.value=p.mid;const hi=c.createBiquadFilter();hi.type='highshelf';hi.frequency.value=4000;hi.gain.value=p.high;const g=c.createGain();g.gain.value=p.lvl*(1-p.wet*.5);chain.push(lo,md,hi,g);
  chain.forEach(n=>{head.connect(n);head=n;nodes.push(n)});g.connect(MASTER);const ir=makeIR(c,.55,.55,{pre:.004,er:8,flutter:0});const w=c.createGain();w.gain.value=p.wet*1.4;hi.connect(ir).connect(w).connect(MASTER);nodes.push(ir,w);return g})};
 render()};
/* rooms */
const ROOMS=[['closet','Wardrobe full of clothes',.12,.25,{er:2}],['treated','Treated home studio',.3,.45,{er:4}],['bedroom','Untreated bedroom',.55,.6,{er:10}],['living','Living room',.7,.5,{er:8}],['bathroom','Tiled bathroom',1.4,.85,{er:14}],['hall','Concert hall',2.4,.5,{pre:.03,er:8}]];
WIDGETS.room=host=>{let rid='bedroom',srcK='clap',flutter=false,dry=false;
 const render=()=>{const R=ROOMS.find(r=>r[0]===rid);host.innerHTML=`<h3>Room simulator</h3><p class="hint">The same sound in different rooms. Listen to how long the tail lasts and how it colours the sound.</p>${pillsHTML('rr',ROOMS.map(r=>[r[0],r[1]]),rid)}
  <div class="row" style="gap:14px;flex-wrap:wrap;align-items:flex-end;margin-top:6px"><div class="pickrow"><span class="eyebrow">Sound</span>${pillsHTML('rs',[['clap','Hand clap'],['voice','Voice'],['snare','Snare'],['strum','Guitar']],srcK)}</div><label class="pill" style="cursor:pointer"><input type="checkbox" id="rfl" ${flutter?'checked':''}> Flutter echo (parallel bare walls)</label><label class="pill" style="cursor:pointer"><input type="checkbox" id="rdry" ${dry?'checked':''}> Dry (no room)</label></div>
  <div class="rt"><span>Reverb time (RT60)</span><i class="hbar"><i style="width:${Math.min(100,R[2]/2.5*100)}%"></i></i><b>${R[2].toFixed(2)} s</b></div><button class="btn primary small" id="rplay">${ICON.play} Hear it</button>`;
  bindPills(host,(g,v)=>{if(g==='rr')rid=v;else srcK=v;render();hear()});host.querySelector('#rfl').onchange=e=>{flutter=e.target.checked;hear()};host.querySelector('#rdry').onchange=e=>{dry=e.target.checked;hear()};host.querySelector('#rplay').onclick=hear};
 const hear=()=>{const R=ROOMS.find(r=>r[0]===rid);playThrough(srcK,(c,s,nodes)=>{const d=c.createGain();d.gain.value=1;s.connect(d).connect(MASTER);nodes.push(d);if(!dry){const ir=makeIR(c,R[2],R[3],{...R[4],flutter:flutter?.009:0});const w=c.createGain();w.gain.value=R[0]==='closet'?.25:R[0]==='treated'?.45:.8;s.connect(ir).connect(w).connect(MASTER);nodes.push(ir,w)}return d})};
 render()};
/* mixer */
WIDGETS.mixer=host=>{const P=Object.assign({hp:false,low:0,midF:400,mid:0,high:0,thr:0,ratio:3,rev:0,bypass:false},{});let raf=0;
 host.innerHTML=`<h3>Try the tools on a mix</h3><p class="hint">Press Play, then change one thing at a time. Use Bypass to compare with the original.</p>
  <div class="row"><button class="btn primary small" id="mxp">${ICON.play} Play the band</button><label class="pill" style="cursor:pointer"><input type="checkbox" id="mxb"> Bypass (hear the original)</label></div>
  <div class="mixgrid"><div class="mini"><h4>EQ</h4><label class="pill" style="cursor:pointer"><input type="checkbox" id="mhp"> High-pass at 120 Hz</label><label class="tempo">Low (100 Hz) <input type="range" id="mlow" min="-12" max="12" value="0"> <span>0 dB</span></label><label class="tempo">Mid freq <input type="range" id="mmf" min="150" max="5000" value="400"> <span>400 Hz</span></label><label class="tempo">Mid gain <input type="range" id="mmid" min="-12" max="12" value="0"> <span>0 dB</span></label><label class="tempo">High (8 kHz) <input type="range" id="mhigh" min="-12" max="12" value="0"> <span>0 dB</span></label></div>
  <div class="mini"><h4>Compressor</h4><label class="tempo">Threshold <input type="range" id="mthr" min="-40" max="0" value="0"> <span>0 dB</span></label><label class="tempo">Ratio <input type="range" id="mrat" min="1" max="12" value="3"> <span>3:1</span></label><p class="hint">Gain reduction</p><div class="grm"><i id="mgr"></i></div><b id="mgrv">0.0 dB</b></div>
  <div class="mini"><h4>Reverb send</h4><label class="tempo">Amount <input type="range" id="mrev" min="0" max="100" value="0"> <span>0%</span></label><p class="hint">A send blends a 100% wet reverb with the dry sound.</p></div></div>`;
 let N=null;const apply=()=>{if(!N)return;N.hp.frequency.value=P.hp?120:10;N.low.gain.value=P.low;N.mid.frequency.value=P.midF;N.mid.gain.value=P.mid;N.high.gain.value=P.high;N.comp.threshold.value=P.thr;N.comp.ratio.value=P.ratio;N.make.gain.value=Math.pow(10,(-P.thr*(1-1/P.ratio)*.5)/20);N.wet.gain.value=P.rev/100*1.2;N.proc.gain.value=P.bypass?0:1;N.raw.gain.value=P.bypass?1:0};
 const tick=()=>{if(!document.body.contains(host)){cancelAnimationFrame(raf);stopDemo();return}if(N){const r=-N.comp.reduction;host.querySelector('#mgr').style.width=Math.min(100,r/20*100)+'%';host.querySelector('#mgrv').textContent=r.toFixed(1)+' dB'}raf=requestAnimationFrame(tick)};
 const bind=(id,key,fmt,conv=x=>x)=>{const r=host.querySelector('#'+id);r.oninput=()=>{P[key]=conv(+r.value);const s=r.nextElementSibling;if(s)s.textContent=fmt(+r.value);apply()}};
 bind('mlow','low',v=>`${v>0?'+':''}${v} dB`);bind('mmf','midF',v=>v>=1000?(v/1000).toFixed(1)+' kHz':v+' Hz');bind('mmid','mid',v=>`${v>0?'+':''}${v} dB`);bind('mhigh','high',v=>`${v>0?'+':''}${v} dB`);bind('mthr','thr',v=>`${v} dB`);bind('mrat','ratio',v=>`${v}:1`);bind('mrev','rev',v=>`${v}%`);
 host.querySelector('#mhp').onchange=e=>{P.hp=e.target.checked;apply()};host.querySelector('#mxb').onchange=e=>{P.bypass=e.target.checked;apply()};
 host.querySelector('#mxp').onclick=async()=>{if(DEMO&&DEMO.kind==='mixer'){stopDemo();N=null;host.querySelector('#mxp').innerHTML=ICON.play+' Play the band';return}host.querySelector('#mxp').textContent='Loading…';
  const d=await playThrough('loop',(c,src,nodes)=>{const hp=c.createBiquadFilter();hp.type='highpass';const low=c.createBiquadFilter();low.type='lowshelf';low.frequency.value=100;const mid=c.createBiquadFilter();mid.type='peaking';mid.Q.value=1;const high=c.createBiquadFilter();high.type='highshelf';high.frequency.value=8000;const comp=c.createDynamicsCompressor();comp.knee.value=6;comp.attack.value=.01;comp.release.value=.15;const make=c.createGain();const proc=c.createGain();const raw=c.createGain();const out=c.createGain();out.gain.value=.8;
   src.connect(hp).connect(low).connect(mid).connect(high).connect(comp).connect(make).connect(proc).connect(out);src.connect(raw).connect(out);const ir=makeIR(c,1.6,.5,{pre:.02,er:6});const wet=c.createGain();make.connect(ir).connect(wet).connect(proc);out.connect(MASTER);nodes.push(hp,low,mid,high,comp,make,proc,raw,out,ir,wet);N={hp,low,mid,high,comp,make,proc,raw,wet};apply();return out},{loop:true});
  if(d)d.kind='mixer';host.querySelector('#mxp').innerHTML='■ Stop';cancelAnimationFrame(raf);tick()}};

